  ccxt::any parseMarket(ccxt::any market) override {
    ccxt::any id = this->safeString(market, std::string("symbol"));
    ccxt::any symbolParts = split(id, std::string("-"));
    ccxt::any baseId = ::getValue(symbolParts, 0);
    ccxt::any quoteId = ::getValue(symbolParts, 1);
    ccxt::any base = this->safeCurrencyCode(baseId);
    ccxt::any quote = this->safeCurrencyCode(quoteId);
    ccxt::any currency = this->safeString(market, std::string("currency"));
    ccxt::any checkIsInverse = false;
    ccxt::any checkIsLinear = true;
    ccxt::any minTickSize =
        this->safeNumber(market, std::string("minTickSize"));
    if (isTrue(!isEqual(minTickSize, ccxt::any{}))) {
      // inverse swap market
      currency = baseId;
      checkIsInverse = true;
      checkIsLinear = false;
    }
    ccxt::any settle = this->safeCurrencyCode(currency);
    ccxt::any pricePrecision =
        this->safeNumber(market, std::string("tickSize"));
    if (isTrue(isEqual(pricePrecision, ccxt::any{}))) {
      pricePrecision = this->parseNumber(this->parsePrecision(
          this->safeString(market, std::string("pricePrecision"))));
    }
    ccxt::any quantityPrecision =
        this->safeNumber(market, std::string("stepSize"));
    if (isTrue(isEqual(quantityPrecision, ccxt::any{}))) {
      quantityPrecision = this->parseNumber(this->parsePrecision(
          this->safeString(market, std::string("quantityPrecision"))));
    }
    ccxt::any type = (isTrue((!isEqual(settle, ccxt::any{})))
                          ? ccxt::any(std::string("swap"))
                          : ccxt::any(std::string("spot")));
    ccxt::any spot = isEqual(type, std::string("spot"));
    ccxt::any swap = isEqual(type, std::string("swap"));
    ccxt::any symbol = add(add(base, std::string("/")), quote);
    if (isTrue(!isEqual(settle, ccxt::any{}))) {
      symbol = add(symbol, add(std::string(":"), settle));
    }
    ccxt::any fees = this->safeDict(this->fees, type, ccxt::dict{});
    ccxt::any contractSize =
        (isTrue((swap)) ? ccxt::any(this->parseNumber(std::string("1")))
                        : ccxt::any(ccxt::any{}));
    ccxt::any isActive = false;
    if (isTrue(isTrue((isEqual(
                   this->safeString(market, std::string("apiStateOpen")),
                   std::string("true")))) &&
               isTrue((isEqual(
                   this->safeString(market, std::string("apiStateClose")),
                   std::string("true")))))) {
      isActive = true; // swap active
    } else if (isTrue(
                   isTrue(
                       isTrue((isEqual(
                           this->safeBool(market, std::string("apiStateSell")),
                           true))) &&
                       isTrue((isEqual(
                           this->safeBool(market, std::string("apiStateBuy")),
                           true)))) &&
                   isTrue(
                       (isEqual(this->safeString(market, std::string("status")),
                                std::string("1")))))) {
      isActive = true; // spot active
    } else if (isTrue(isTrue(checkIsInverse) &&
                      isTrue((isEqual(
                          this->safeString(market, std::string("status")),
                          std::string("1")))))) {
      isActive = true; // inverse swap active
    }
    ccxt::any isInverse =
        (isTrue((spot)) ? ccxt::any(ccxt::any{}) : ccxt::any(checkIsInverse));
    ccxt::any isLinear =
        (isTrue((spot)) ? ccxt::any(ccxt::any{}) : ccxt::any(checkIsLinear));
    ccxt::any minAmount = ccxt::any{};
    if (!isTrue(spot)) {
      minAmount = this->safeNumber2(market, std::string("minQty"),
                                    std::string("tradeMinQuantity"));
    }
    ccxt::any timeOnline = this->safeInteger(market, std::string("timeOnline"));
    if (isTrue(isEqual(timeOnline, 0))) {
      timeOnline = ccxt::any{};
    }
    return this->safeMarketStructure(ccxt::dict{
        {std::string("id"), id},
        {std::string("symbol"), symbol},
        {std::string("base"), base},
        {std::string("quote"), quote},
        {std::string("settle"), settle},
        {std::string("baseId"), baseId},
        {std::string("quoteId"), quoteId},
        {std::string("settleId"), currency},
        {std::string("type"), type},
        {std::string("spot"), spot},
        {std::string("margin"), false},
        {std::string("swap"), swap},
        {std::string("future"), false},
        {std::string("option"), false},
        {std::string("active"), isActive},
        {std::string("contract"), swap},
        {std::string("linear"), isLinear},
        {std::string("inverse"), isInverse},
        {std::string("taker"), this->safeNumber(fees, std::string("taker"))},
        {std::string("maker"), this->safeNumber(fees, std::string("maker"))},
        {std::string("feeSide"),
         this->safeString(fees, std::string("feeSide"))},
        {std::string("contractSize"), contractSize},
        {std::string("expiry"), ccxt::any{}},
        {std::string("expiryDatetime"), ccxt::any{}},
        {std::string("strike"), ccxt::any{}},
        {std::string("optionType"), ccxt::any{}},
        {std::string("precision"),
         ccxt::dict{
             {std::string("amount"), quantityPrecision},
             {std::string("price"), pricePrecision},
         }},
        {std::string("limits"),
         ccxt::dict{
             {std::string("leverage"),
              ccxt::dict{
                  {std::string("min"), ccxt::any{}},
                  {std::string("max"), ccxt::any{}},
              }},
             {std::string("amount"),
              ccxt::dict{
                  {std::string("min"), minAmount},
                  {std::string("max"), ccxt::any{}},
              }},
             {std::string("price"),
              ccxt::dict{
                  {std::string("min"), minTickSize},
                  {std::string("max"), ccxt::any{}},
              }},
             {std::string("cost"),
              ccxt::dict{
                  {std::string("min"),
                   this->safeNumberN(market,
                                     ccxt::list{std::string("minNotional"),
                                                std::string("tradeMinUSDT"),
                                                std::string("minTradeValue")})},
                  {std::string("max"),
                   this->safeNumber(market, std::string("maxNotional"))},
              }},
         }},
        {std::string("created"), timeOnline},
        {std::string("info"), market},
    });
  }

  /**
   * @method
   * @name bingx#fetchMarkets
   * @description retrieves data on all markets for bingx
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Spot/Market%20Data/Spot%20trading%20symbols
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Swap/Market%20Data/USDT-M%20Perp%20Futures%20symbols
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Coin-M%20Futures/Market%20Data/Contract%20Information
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} an array of objects representing market data
   */
  std::shared_future<ccxt::any>
  fetchMarkets(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any requests =
                     ccxt::list{this->fetchSwapMarkets(params)};
                 ccxt::any isSandbox = this->safeBool(
                     this->options, std::string("sandboxMode"), false);
                 if (isTrue(!isEqual(isSandbox, true))) {
                   arrayPush(requests, this->fetchInverseSwapMarkets(params));
                   arrayPush(requests, this->fetchSpotMarkets(
                                           params)); // sandbox is swap only
                 }
                 ccxt::any promises = awaitValue(promiseAll(requests));
                 ccxt::any linearSwapMarkets =
                     this->safeList(promises, 0, ccxt::list{});
                 ccxt::any inverseSwapMarkets =
                     this->safeList(promises, 1, ccxt::list{});
                 ccxt::any spotMarkets =
                     this->safeList(promises, 2, ccxt::list{});
                 ccxt::any swapMarkets =
                     this->arrayConcat(linearSwapMarkets, inverseSwapMarkets);
                 return this->arrayConcat(spotMarkets, swapMarkets);
               })
        .share();
  }

  /**
   * @method
   * @name bingx#fetchOHLCV
   * @description fetches historical candlestick data containing the open, high,
   * low, and close price, and the volume of a market
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Spot/Market%20Data/Kline%2FCandlestick%20Data
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Swap/Market%20Data/Kline%2FCandlestick%20Data
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Swap/Market%20Data/Mark%20Price%20Kline%2FCandlestick%20Data
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Coin-M%20Futures/Market%20Data/Get%20K-line%20Data
   * @param {string} symbol unified symbol of the market to fetch OHLCV data for
   * @param {string} timeframe the length of time each candle represents
   * @param {int} [since] timestamp in ms of the earliest candle to fetch
   * @param {int} [limit] the maximum amount of candles to fetch (max 1000 for
   * inverse swaps, 1440 otherwise)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms of the latest candle to fetch
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [available
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {int[][]} A list of candles ordered as timestamp, open, high, low,
   * close, volume
   */
  std::shared_future<ccxt::any>
  fetchOHLCV(ccxt::any symbol, ccxt::any timeframe = std::string("1m"),
             ccxt::any since = ccxt::any{}, ccxt::any limit = ccxt::any{},
             ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any maxLimit =
                     (isTrue((isEqual(
                          ::getValue(market, std::string("inverse")), true)))
                          ? ccxt::any(1000)
                          : ccxt::any(1440));
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchOHLCV"), std::string("paginate"),
                     false);
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDeterministic(
                       std::string("fetchOHLCV"), symbol, since, limit,
                       timeframe, params, maxLimit));
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 ::setValue(
                     request, std::string("interval"),
                     this->safeString(this->timeframes, timeframe, timeframe));
                 ccxt::any requestLimit =
                     (isTrue((isEqual(limit, ccxt::any{})))
                          ? ccxt::any(500)
                          : ccxt::any(mathMin(limit, maxLimit)));
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("startTime"),
                              mathMax(subtract(since, 1), 0));
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), requestLimit);
                 }
                 ccxt::any until = this->safeInteger2(
                     params, std::string("until"), std::string("endTime"));
                 if (isTrue(!isEqual(until, ccxt::any{}))) {
                   params =
                       this->omit(params, ccxt::list{std::string("until")});
                   ::setValue(request, std::string("endTime"), until);
                 } else if (isTrue(
                                isTrue((isEqual(
                                    ::getValue(market, std::string("inverse")),
                                    true))) &&
                                isTrue((!isEqual(since, ccxt::any{}))))) {
                   ccxt::any duration =
                       multiply(this->parseTimeframe(timeframe), 1000);
                   ::setValue(
                       request, std::string("endTime"),
                       this->sum(since, multiply(duration, requestLimit)));
                 }
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("spot")),
                                    true))) {
                   // bingx spot klines are anchored to UTC+8 by default, unlike
                   // the swap klines and other exchanges the timeZone request
                   // parameter aligns the candle boundaries to UTC,
                   // live-verified for the spot endpoint
                   ccxt::any timeZone = ccxt::any{};
                   ccxt::any timeZoneparamsVariable =
                       this->handleOptionAndParams(params,
                                                   std::string("fetchOHLCV"),
                                                   std::string("timeZone"), 0);
                   timeZone = ::getValue(timeZoneparamsVariable, 0);
                   params = ::getValue(timeZoneparamsVariable, 1);
                   if (isTrue(!isEqual(timeZone, ccxt::any{}))) {
                     ::setValue(request, std::string("timeZone"), timeZone);
                   }
                   response = awaitValue(this->spotV1PublicGetMarketKline(
                       this->extend(request, params)));
                 } else {
                   if (isTrue(isEqual(
                           ::getValue(market, std::string("inverse")), true))) {
                     response = awaitValue(this->cswapV1PublicGetMarketKlines(
                         this->extend(request, params)));
                   } else {
                     ccxt::any price =
                         this->safeString(params, std::string("price"));
                     params = this->omit(params, std::string("price"));
                     if (isTrue(isEqual(price, std::string("mark")))) {
                       response = awaitValue(
                           this->swapV1PublicGetMarketMarkPriceKlines(
                               this->extend(request, params)));
                     } else {
                       response = awaitValue(this->swapV3PublicGetQuoteKlines(
                           this->extend(request, params)));
                     }
                   }
                 }
                 //
                 //    {
                 //        "code": 0,
                 //        "msg": "",
                 //        "data": [
                 //          {
                 //            "open": "19396.8",
                 //            "close": "19394.4",
                 //            "high": "19397.5",
                 //            "low": "19385.7",
                 //            "volume": "110.05",
                 //            "time": 1666583700000
                 //          },
                 //          ...
                 //        ]
                 //    }
                 //
                 // fetchMarkOHLCV
                 //
                 //    {
                 //        "code": 0,
                 //        "msg": "",
                 //        "data": [
                 //            {
                 //                "open": "42191.7",
                 //                "close": "42189.5",
                 //                "high": "42196.5",
                 //                "low": "42189.5",
                 //                "volume": "0.00",
                 //                "openTime": 1706508840000,
                 //                "closeTime": 1706508840000
                 //            }
                 //        ]
                 //    }
                 //
                 ccxt::any ohlcvs = this->safeValue(
                     response, std::string("data"), ccxt::list{});
                 if (!isTrue(isArray(ohlcvs))) {
                   ohlcvs = ccxt::list{ohlcvs};
                 }
                 return this->parseOHLCVs(ohlcvs, market, timeframe, since,
                                          limit);
               })
        .share();
  }

  ccxt::any parseOHLCV(ccxt::any ohlcv,
                       ccxt::any market = ccxt::any{}) override {
    //
    //    {
    //        "open": "19394.4",
    //        "close": "19379.0",
    //        "high": "19394.4",
    //        "low": "19368.3",
    //        "volume": "167.44",
    //        "time": 1666584000000
    //    }
    //
    // fetchMarkOHLCV
    //
    //    {
    //        "open": "42191.7",
    //        "close": "42189.5",
    //        "high": "42196.5",
    //        "low": "42189.5",
    //        "volume": "0.00",
    //        "openTime": 1706508840000,
    //        "closeTime": 1706508840000
    //    }
    // spot
    //    [
    //        1691402580000,
    //        29093.61,
    //        29093.93,
    //        29087.73,
    //        29093.24,
    //        0.59,
    //        1691402639999,
    //        17221.07
    //    ]
    //
    if (isTrue(isArray(ohlcv))) {
      return ccxt::list{
          this->safeInteger(ohlcv, 0), this->safeNumber(ohlcv, 1),
          this->safeNumber(ohlcv, 2),  this->safeNumber(ohlcv, 3),
          this->safeNumber(ohlcv, 4),  this->safeNumber(ohlcv, 5)};
    }
    return ccxt::list{this->safeInteger2(ohlcv, std::string("time"),
                                         std::string("closeTime")),
                      this->safeNumber(ohlcv, std::string("open")),
                      this->safeNumber(ohlcv, std::string("high")),
                      this->safeNumber(ohlcv, std::string("low")),
                      this->safeNumber(ohlcv, std::string("close")),
                      this->safeNumber(ohlcv, std::string("volume"))};
  }

  /**
   * @method
   * @name bingx#fetchTrades
   * @description get the list of most recent trades for a particular symbol
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Spot/Market%20Data/Recent%20Trades%20List
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Swap/Market%20Data/Recent%20Trades%20List
   * @param {string} symbol unified symbol of the market to fetch trades for
   * @param {int} [since] timestamp in ms of the earliest trade to fetch
   * @param {int} [limit] the maximum amount of trades to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [trade structures]{@link
   * https://docs.ccxt.com/?id=public-trades}
   */
  std::shared_future<ccxt::any>
  fetchTrades(ccxt::any symbol, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 if (isTrue(isEqual(::getValue(market, std::string("inverse")),
                                    true))) {
                   throw NotSupported(toString(add(
                       this->id, std::string(" fetchTrades() is not supported "
                                             "for inverse swap markets"))));
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 ccxt::any response = ccxt::any{};
                 ccxt::any marketType = ccxt::any{};
                 ccxt::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(std::string("fetchTrades"),
                                                     market, params);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ccxt::any maxLimit =
                       (isTrue((isEqual(marketType, std::string("spot"))))
                            ? ccxt::any(500)
                            : ccxt::any(1000));
                   ::setValue(request, std::string("limit"),
                              mathMin(limit, maxLimit));
                 }
                 if (isTrue(isEqual(marketType, std::string("spot")))) {
                   response = awaitValue(this->spotV1PublicGetMarketTrades(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(this->swapV2PublicGetQuoteTrades(
                       this->extend(request, params)));
                 }
                 //
                 // spot
                 //
                 //    {
                 //        "code": 0,
                 //        "data": [
                 //            {
                 //                "id": 43148253,
                 //                "price": 25714.71,
                 //                "qty": 1.674571,
                 //                "time": 1655085975589,
                 //                "buyerMaker": false
                 //            }
                 //        ]
                 //    }
                 //
                 // swap
                 //
                 //    {
                 //      "code":0,
                 //      "msg":"",
                 //      "data":[
                 //        {
                 //          "time": 1672025549368,
                 //          "isBuyerMaker": true,
                 //          "price": "16885.0",
                 //          "qty": "3.3002",
                 //          "quoteQty": "55723.87"
                 //        },
                 //        ...
                 //      ]
                 //    }
                 //
                 ccxt::any trades = this->safeList(
                     response, std::string("data"), ccxt::list{});
                 return this->parseTrades(trades, market, since, limit);
               })
        .share();
  }

  ccxt::any parseTrade(ccxt::any trade,
                       ccxt::any market = ccxt::any{}) override {
    //
    // spot fetchTrades
    //
    //    {
    //        "id": 43148253,
    //        "price": 25714.71,
    //        "qty": 1.674571,
    //        "time": 1655085975589,
    //        "buyerMaker": false
    //    }
    //
    // spot fetchMyTrades
    //
    //     {
    //         "symbol": "LTC-USDT",
    //         "id": 36237072,
    //         "orderId": 1674069326895775744,
    //         "price": "85.891",
    //         "qty": "0.0582",
    //         "quoteQty": "4.9988562000000005",
    //         "commission": -0.00005820000000000001,
    //         "commissionAsset": "LTC",
    //         "time": 1687964205000,
    //         "isBuyer": true,
    //         "isMaker": false
    //     }
    //
    // swap fetchTrades
    //
    //    {
    //        "time": 1672025549368,
    //        "isBuyerMaker": true,
    //        "price": "16885.0",
    //        "qty": "3.3002",
    //        "quoteQty": "55723.87"
    //    }
    //
    // swap fetchMyTrades
    //
    //    {
    //        "volume": "0.1",
    //        "price": "106.75",
    //        "amount": "10.6750",
    //        "commission": "-0.0053",
    //        "currency": "USDT",
    //        "orderId": "1676213270274379776",
    //        "liquidatedPrice": "0.00",
    //        "liquidatedMarginRatio": "0.00",
    //        "filledTime": "2023-07-04T20:56:01.000+0800"
    //    }
    //
    // ws spot
    //
    //    {
    //        "E": 1690214529432,
    //        "T": 1690214529386,
    //        "e": "trade",
    //        "m": true,
    //        "p": "29110.19",
    //        "q": "0.1868",
    //        "s": "BTC-USDT",
    //        "t": "57903921"
    //    }
    //
    // ws linear swap
    //
    //    {
    //        "q": "0.0421",
    //        "p": "29023.5",
    //        "T": 1690221401344,
    //        "m": false,
    //        "s": "BTC-USDT"
    //    }
    //
    // ws inverse swap
    //
    //     {
    //         "e": "trade",
    //         "E": 1722920589665,
    //         "s": "BTC-USD",
    //         "t": "39125001",
    //         "p": "55360.0",
    //         "q": "1",
    //         "T": 1722920589582,
    //         "m": false
    //     }
    //
    // inverse swap fetchMyTrades
    //
    //     {
    //         "orderId": "1817441228670648320",
    //         "symbol": "SOL-USD",
    //         "type": "MARKET",
    //         "side": "BUY",
    //         "positionSide": "LONG",
    //         "tradeId": "97244554",
    //         "volume": "2",
    //         "tradePrice": "182.652",
    //         "amount": "20.00000000",
    //         "realizedPnl": "0.00000000",
    //         "commission": "-0.00005475",
    //         "currency": "SOL",
    //         "buyer": true,
    //         "maker": false,
    //         "tradeTime": 1722146730000
    //     }
    //
    ccxt::any time = this->safeIntegerN(
        trade, ccxt::list{std::string("time"), std::string("filledTm"),
                          std::string("T"), std::string("tradeTime")});
    ccxt::any datetimeId = this->safeString(trade, std::string("filledTm"));
    if (isTrue(!isEqual(datetimeId, ccxt::any{}))) {
      time = this->parse8601(datetimeId);
    }
    if (isTrue(isEqual(time, 0))) {
      time = ccxt::any{};
    }
    ccxt::any cost = this->safeString(trade, std::string("quoteQty"));
    // const type = (cost === undefined) ? 'spot' : 'swap'; this is not reliable
    ccxt::any currencyId = this->safeStringN(
        trade, ccxt::list{std::string("currency"), std::string("N"),
                          std::string("commissionAsset")});
    ccxt::any currencyCode = this->safeCurrencyCode(currencyId);
    ccxt::any m = this->safeBool(trade, std::string("m"));
    ccxt::any marketId =
        this->safeString2(trade, std::string("s"), std::string("symbol"));
    ccxt::any isBuyerMaker = this->safeBoolN(
        trade, ccxt::list{std::string("buyerMaker"),
                          std::string("isBuyerMaker"), std::string("maker")});
    ccxt::any takeOrMaker = ccxt::any{};
    ccxt::any isMakerSide =
        isTrue((isEqual(isBuyerMaker, true))) || isTrue((isEqual(m, true)));
    if (isTrue(isTrue((!isEqual(isBuyerMaker, ccxt::any{}))) ||
               isTrue((!isEqual(m, ccxt::any{}))))) {
      takeOrMaker = (isTrue(isMakerSide) ? ccxt::any(std::string("maker"))
                                         : ccxt::any(std::string("taker")));
    }
    ccxt::any side =
        this->safeStringLower2(trade, std::string("side"), std::string("S"));
    if (isTrue(isEqual(side, ccxt::any{}))) {
      if (isTrue(isTrue((!isEqual(isBuyerMaker, ccxt::any{}))) ||
                 isTrue((!isEqual(m, ccxt::any{}))))) {
        side = (isTrue(isMakerSide) ? ccxt::any(std::string("sell"))
                                    : ccxt::any(std::string("buy")));
        takeOrMaker = std::string("taker");
      }
    }
    ccxt::any isBuyer = this->safeBool(trade, std::string("isBuyer"));
    if (isTrue(!isEqual(isBuyer, ccxt::any{}))) {
      side = (isTrue(isBuyer) ? ccxt::any(std::string("buy"))
                              : ccxt::any(std::string("sell")));
    }
    ccxt::any isMaker = this->safeBool(trade, std::string("isMaker"));
    if (isTrue(!isEqual(isMaker, ccxt::any{}))) {
      takeOrMaker = (isTrue(isMaker) ? ccxt::any(std::string("maker"))
                                     : ccxt::any(std::string("taker")));
    }
    ccxt::any amount = this->safeStringN(
        trade, ccxt::list{std::string("qty"), std::string("amount"),
                          std::string("q")});
    if (isTrue(isTrue(isTrue((!isEqual(market, ccxt::any{}))) &&
                      isTrue((isEqual(::getValue(market, std::string("swap")),
                                      true)))) &&
               isTrue((inOp(trade, std::string("volume")))))) {
      if (isTrue(isEqual(::getValue(market, std::string("linear")), true))) {
        // private linear swap trades report 'amount' as the notional (quote)
        // value, not the base amount; 'volume' is the exchange's own
        // base-currency fill quantity (bingx linear contractSize is always 1),
        // use it directly instead of 'notional / price', which picks up
        // rounding noise from the notional field
        amount = this->safeString(trade, std::string("volume"));
      } else {
        // private trade returns num of contracts instead of base currency (as
        // the order-related methods do)
        ccxt::any contractSize =
            this->safeString(::getValue(market, std::string("info")),
                             std::string("tradeMinQuantity"));
        ccxt::any volume = this->safeString(trade, std::string("volume"));
        amount = ccxt::Precise::stringMul(volume, contractSize);
      }
    }
    return this->safeTrade(
        ccxt::dict{
            {std::string("id"),
             this->safeString2(trade, std::string("id"), std::string("t"))},
            {std::string("info"), trade},
            {std::string("timestamp"), time},
            {std::string("datetime"), this->iso8601(time)},
            {std::string("symbol"),
             this->safeSymbol(marketId, market, std::string("-"))},
            {std::string("order"),
             this->safeString2(trade, std::string("orderId"),
                               std::string("i"))},
            {std::string("type"),
             this->safeStringLower(trade, std::string("o"))},
            {std::string("side"), this->parseOrderSide(side)},
            {std::string("takerOrMaker"), takeOrMaker},
            {std::string("price"),
             this->safeStringN(trade, ccxt::list{std::string("price"),
                                                 std::string("p"),
                                                 std::string("tradePrice")})},
            {std::string("amount"), amount},
            {std::string("cost"), cost},
            {std::string("fee"),
             ccxt::dict{
                 {std::string("cost"),
                  this->parseNumber(ccxt::Precise::stringAbs(this->safeString2(
                      trade, std::string("commission"), std::string("n"))))},
                 {std::string("currency"), currencyCode},
             }},
        },
        market);
  }

  /**
   * @method
   * @name bingx#fetchOrderBook
   * @description fetches information on open orders with bid (buy) and ask
   * (sell) prices, volumes and other data
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Spot/Market%20Data/Order%20Book
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Swap/Market%20Data/Order%20Book
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Coin-M%20Futures/Market%20Data/Query%20Depth%20Data
   * @param {string} symbol unified symbol of the market to fetch the order book
   * for
   * @param {int} [limit] the maximum amount of order book entries to return
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order book structure]{@link
   * https://docs.ccxt.com/?id=order-book-structure}
   */
  std::shared_future<ccxt::any>
  fetchOrderBook(ccxt::any symbol, ccxt::any limit = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ccxt::any response = ccxt::any{};
                 ccxt::any marketType = ccxt::any{};
                 ccxt::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(
                         std::string("fetchOrderBook"), market, params);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 if (isTrue(isEqual(marketType, std::string("spot")))) {
                   response = awaitValue(this->spotV1PublicGetMarketDepth(
                       this->extend(request, params)));
                 } else {
                   if (isTrue(isEqual(
                           ::getValue(market, std::string("inverse")), true))) {
                     response = awaitValue(this->cswapV1PublicGetMarketDepth(
                         this->extend(request, params)));
                   } else {
                     response = awaitValue(this->swapV2PublicGetQuoteDepth(
                         this->extend(request, params)));
                   }
                 }
                 //
                 // spot
                 //
                 //     {
                 //         "code":0,
                 //         "timestamp":1743240504535,
                 //         "data":{
                 //             "bids":[
                 //                 ["83775.39","1.981875"],
                 //                 ["83775.38","0.001076"],
                 //                 ["83775.34","0.254716"],
                 //             ],
                 //             "asks":[
                 //                 ["83985.40","0.000013"],
                 //                 ["83980.00","0.000011"],
                 //                 ["83975.70","0.000061000000000000005"],
                 //             ],
                 //             "ts":1743240504535,
                 //             "lastUpdateId":13565639906
                 //         }
                 //     }
                 //
                 //
                 // linear swap
                 //
                 //     {
                 //         "code":0,
                 //         "msg":"",
                 //         "data":{
                 //             "T":1743240836255,
                 //             "bids":[
                 //                 ["83760.7","7.0861"],
                 //                 ["83760.6","0.0044"],
                 //                 ["83757.7","1.9526"],
                 //             ],
                 //             "asks":[
                 //                 ["83784.3","8.3531"],
                 //                 ["83782.8","23.7289"],
                 //                 ["83780.1","18.0617"],
                 //             ],
                 //             "bidsCoin":[
                 //                 ["83760.7","0.0007"],
                 //                 ["83760.6","0.0000"],
                 //                 ["83757.7","0.0002"],
                 //             ],
                 //             "asksCoin":[
                 //                 ["83784.3","0.0008"],
                 //                 ["83782.8","0.0024"],
                 //                 ["83780.1","0.0018"],
                 //             ]
                 //         }
                 //     }
                 //
                 // inverse swap
                 //
                 //     {
                 //         "code":0,
                 //         "msg":"",
                 //         "timestamp":1743240979146,
                 //         "data":{
                 //             "T":1743240978691,
                 //             "bids":[
                 //                 ["83611.4","241.0"],
                 //                 ["83611.3","1.0"],
                 //                 ["83602.9","666.0"],
                 //             ],
                 //             "asks":[
                 //                 ["83645.0","4253.0"],
                 //                 ["83640.5","3188.0"],
                 //                 ["83636.0","5540.0"],
                 //             ]
                 //         }
                 //     }
                 //
                 ccxt::any orderbook = this->safeDict(
                     response, std::string("data"), ccxt::dict{});
                 ccxt::any nonce =
                     this->safeInteger(orderbook, std::string("lastUpdateId"));
                 ccxt::any timestamp = this->safeInteger2(
                     orderbook, std::string("T"), std::string("ts"));
                 ccxt::any result = this->parseOrderBook(
                     orderbook, ::getValue(market, std::string("symbol")),
                     timestamp, std::string("bids"), std::string("asks"), 0, 1);
                 ::setValue(result, std::string("nonce"), nonce);
                 return result;
               })
        .share();
  }

  /**
   * @method
   * @name bingx#fetchFundingRate
   * @description fetch the current funding rate
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Swap/Market%20Data/Mark%20Price%20and%20Funding%20Rate
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Coin-M%20Futures/Market%20Data/Price%20%26%20Current%20Funding%20Rate
   * @param {string} symbol unified market symbol
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [funding rate structure]{@link
   * https://docs.ccxt.com/?id=funding-rate-structure}
   */
  std::shared_future<ccxt::any>
  fetchFundingRate(ccxt::any symbol, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("inverse")),
                                    true))) {
                   response =
                       awaitValue(this->cswapV1PublicGetMarketPremiumIndex(
                           this->extend(request, params)));
                 } else {
                   response = awaitValue(this->swapV2PublicGetQuotePremiumIndex(
                       this->extend(request, params)));
                 }
                 //
                 //    {
                 //        "code":0,
                 //        "msg":"",
                 //        "data":[
                 //          {
                 //            "symbol": "BTC-USDT",
                 //            "markPrice": "16884.5",
                 //            "indexPrice": "16886.9",
                 //            "lastFundingRate": "0.0001",
                 //            "nextFundingTime": 1672041600000
                 //          },
                 //          ...
                 //        ]
                 //    }
                 //
                 ccxt::any data = ccxt::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("inverse")),
                                    true))) {
                   ccxt::any dataList = this->safeList(
                       response, std::string("data"), ccxt::list{});
                   data = this->safeDict(dataList, 0, ccxt::dict{});
                 } else {
                   data = this->safeDict(response, std::string("data"),
                                         ccxt::dict{});
                 }
                 return this->parseFundingRate(data, market);
               })
        .share();
  }

  /**
   * @method
   * @name bingx#fetchFundingRates
   * @description fetch the current funding rate for multiple symbols
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Swap/Market%20Data/Mark%20Price%20and%20Funding%20Rate
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Coin-M%20Futures/Market%20Data/Price%20%26%20Current%20Funding%20Rate
   * @param {string[]} [symbols] list of unified market symbols
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.subType] "linear" or "inverse" (default is linear)
   * @returns {object[]} a list of [funding rate structures]{@link
   * https://docs.ccxt.com/?id=funding-rate-structure}
   */
  std::shared_future<ccxt::any>
  fetchFundingRates(ccxt::any symbols = ccxt::any{},
                    ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 symbols = this->marketSymbols(symbols, std::string("swap"),
                                               true, true, true);
                 ccxt::any firstMarket = this->getMarketFromSymbols(symbols);
                 ccxt::any subType = std::string("linear");
                 ccxt::any subTypeparamsVariable = this->handleSubTypeAndParams(
                     std::string("fetchFundingRates"), firstMarket, params,
                     subType);
                 subType = ::getValue(subTypeparamsVariable, 0);
                 params = ::getValue(subTypeparamsVariable, 1);
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(subType, std::string("inverse")))) {
                   response = awaitValue(
                       this->cswapV1PublicGetMarketPremiumIndex(params));
                 } else {
                   response = awaitValue(
                       this->swapV2PublicGetQuotePremiumIndex(params));
                 }
                 ccxt::any data = this->safeList(response, std::string("data"),
                                                 ccxt::list{});
                 return this->parseFundingRates(data, symbols);
               })
        .share();
  }

  ccxt::any parseFundingRate(ccxt::any contract,
                             ccxt::any market = ccxt::any{}) override {
    //
    //     {
    //         "symbol": "BTC-USDT",
    //         "markPrice": "16884.5",
    //         "indexPrice": "16886.9",
    //         "lastFundingRate": "0.0001",
    //         "nextFundingTime": 1672041600000
    //     }
    //
    ccxt::any marketId = this->safeString(contract, std::string("symbol"));
    ccxt::any nextFundingTimestamp =
        this->safeInteger(contract, std::string("nextFundingTime"));
    return ccxt::dict{
        {std::string("info"), contract},
        {std::string("symbol"),
         this->safeSymbol(marketId, market, std::string("-"),
                          std::string("swap"))},
        {std::string("markPrice"),
         this->safeNumber(contract, std::string("markPrice"))},
        {std::string("indexPrice"),
         this->safeNumber(contract, std::string("indexPrice"))},
        {std::string("interestRate"), ccxt::any{}},
        {std::string("estimatedSettlePrice"), ccxt::any{}},
        {std::string("timestamp"), ccxt::any{}},
        {std::string("datetime"), ccxt::any{}},
        {std::string("fundingRate"),
         this->safeNumber(contract, std::string("lastFundingRate"))},
        {std::string("fundingTimestamp"), ccxt::any{}},
        {std::string("fundingDatetime"), ccxt::any{}},
        {std::string("nextFundingRate"), ccxt::any{}},
        {std::string("nextFundingTimestamp"), nextFundingTimestamp},
        {std::string("nextFundingDatetime"),
         this->iso8601(nextFundingTimestamp)},
        {std::string("previousFundingRate"), ccxt::any{}},
        {std::string("previousFundingTimestamp"), ccxt::any{}},
        {std::string("previousFundingDatetime"), ccxt::any{}},
        {std::string("interval"), ccxt::any{}},
    };
  }

  /**
   * @method
   * @name bingx#fetchFundingRateHistory
   * @description fetches historical funding rate prices
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Swap/Market%20Data/Get%20Funding%20Rate%20History
   * @param {string} symbol unified symbol of the market to fetch the funding
   * rate history for, inverse (Coin-M) markets are not supported
   * @param {int} [since] timestamp in ms of the earliest funding rate to fetch
   * @param {int} [limit] the maximum amount of [funding rate structures]{@link
   * https://docs.ccxt.com/?id=funding-rate-history-structure} to fetch (max
   * 1000)
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms of the latest funding rate to
   * fetch
   * @param {boolean} [params.paginate] default false, when true will
   * automatically paginate by calling this endpoint multiple times. See in the
   * docs all the [availble
   * parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
   * @returns {object[]} a list of [funding rate structures]{@link
   * https://docs.ccxt.com/?id=funding-rate-history-structure}
   */
  std::shared_future<ccxt::any> fetchFundingRateHistory(
      ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(symbol, ccxt::any{}))) {
                   throw ArgumentsRequired(toString(add(
                       this->id, std::string(" fetchFundingRateHistory() "
                                             "requires a symbol argument"))));
                 }
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 if (isTrue(isEqual(::getValue(market, std::string("inverse")),
                                    true))) {
                   throw NotSupported(toString(
                       add(this->id,
                           std::string(" fetchFundingRateHistory() is not "
                                       "supported for inverse swap markets"))));
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchFundingRateHistory"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDeterministic(
                       std::string("fetchFundingRateHistory"), symbol, since,
                       limit, std::string("8h"), params));
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("startTime"), since);
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"),
                              mathMin(limit, 1000)); // api maximum 1000
                 }
                 ccxt::any requestparamsVariable = this->handleUntilOption(
                     std::string("endTime"), request, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 ccxt::any response =
                     awaitValue(this->swapV2PublicGetQuoteFundingRate(
                         this->extend(request, params)));
                 //
                 //    {
                 //        "code":0,
                 //        "msg":"",
                 //        "data":[
                 //          {
                 //            "symbol": "BTC-USDT",
                 //            "fundingRate": "0.0001",
                 //            "fundingTime": 1585684800000
                 //          },
                 //          ...
                 //        ]
                 //    }
                 //
                 ccxt::any data = this->safeList(response, std::string("data"),
                                                 ccxt::list{});
                 return this->parseFundingRateHistories(data, market, since,
                                                        limit);
               })
        .share();
  }

  ccxt::any parseFundingRateHistory(ccxt::any contract,
                                    ccxt::any market = ccxt::any{}) override {
    //
    //     {
    //         "symbol": "BTC-USDT",
    //         "fundingRate": "0.0001",
    //         "fundingTime": 1585684800000
    //     }
    //
    ccxt::any timestamp =
        this->safeInteger(contract, std::string("fundingTime"));
    return ccxt::dict{
        {std::string("info"), contract},
        {std::string("symbol"),
         this->safeSymbol(this->safeString(contract, std::string("symbol")),
                          market, std::string("-"), std::string("swap"))},
        {std::string("fundingRate"),
         this->safeNumber(contract, std::string("fundingRate"))},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
    };
  }

  /**
   * @method
   * @name bingx#fetchFundingHistory
   * @description fetches historical funding received
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Swap/Account%20Endpoints/Get%20Account%20Profit%20and%20Loss%20Fund%20Flow
   * @param {string} symbol unified symbol of the market to fetch the funding
   * history for
   * @param {int} [since] timestamp in ms of the earliest funding to fetch
   * @param {int} [limit] the maximum amount of [funding history
   * structures]{@link https://docs.ccxt.com/?id=funding-history-structure} to
   * fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] timestamp in ms of the latest funding to fetch
   * @returns {object[]} a list of [funding history structures]{@link
   * https://docs.ccxt.com/?id=funding-history-structure}
   */
  std::shared_future<ccxt::any> fetchFundingHistory(
      ccxt::any symbol = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any paginate = false;
                 ccxt::any paginateparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchFundingHistory"),
                     std::string("paginate"));
                 paginate = ::getValue(paginateparamsVariable, 0);
                 params = ::getValue(paginateparamsVariable, 1);
                 if (isTrue(paginate)) {
                   return awaitValue(this->fetchPaginatedCallDeterministic(
                       std::string("fetchFundingHistory"), symbol, since, limit,
                       std::string("24h"), params));
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("incomeType"), std::string("FUNDING_FEE")},
                 };
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(request, std::string("symbol"),
                              ::getValue(market, std::string("id")));
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("startTime"), since);
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ccxt::any until = this->safeInteger2(
                     params, std::string("until"), std::string("endTime"));
                 if (isTrue(!isEqual(until, ccxt::any{}))) {
                   params =
                       this->omit(params, ccxt::list{std::string("until")});
                   ::setValue(request, std::string("endTime"), until);
                 }
                 ccxt::any response =
                     awaitValue(this->swapV2PrivateGetUserIncome(
                         this->extend(request, params)));
                 //         {
                 //             "code": 0,
                 //             "msg": "",
                 //             "data": [
                 //                 {
                 //                 "symbol": "LDO-USDT",
                 //                 "incomeType": "FUNDING_FEE",
                 //                 "income": "-0.0292",
                 //                 "asset": "USDT",
                 //                 "info": "Funding Fee",
                 //                 "time": 1702713615000,
                 //                 "tranId": "170***6*2_3*9_20***97",
                 //                 "tradeId": "170***6*2_3*9_20***97"
                 //                 }
                 //             ]
                 //         }
                 ccxt::any data = this->safeList(response, std::string("data"),
                                                 ccxt::list{});
                 return this->parseIncomes(data, market, since, limit);
               })
        .share();
  }

  ccxt::any parseIncome(ccxt::any income,
                        ccxt::any market = ccxt::any{}) override {
    // {
    //     "symbol": "LDO-USDT",
    //     "incomeType": "FUNDING_FEE",
    //     "income": "-0.0292",
    //     "asset": "USDT",
    //     "info": "Funding Fee",
    //     "time": 1702713615000,
    //     "tranId": "170***6*2_3*9_20***97",
    //     "tradeId": "170***6*2_3*9_20***97"
    // }
    ccxt::any marketId = this->safeString(income, std::string("symbol"));
    ccxt::any currencyId = this->safeString(income, std::string("asset"));
    ccxt::any timestamp = this->safeInteger(income, std::string("time"));
    return ccxt::dict{
        {std::string("info"), income},
        {std::string("symbol"),
         this->safeSymbol(marketId, market, ccxt::any{}, std::string("swap"))},
        {std::string("code"), this->safeCurrencyCode(currencyId)},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("id"), this->safeString(income, std::string("tranId"))},
        {std::string("amount"),
         this->safeNumber(income, std::string("income"))},
        {std::string("type"), std::string("funding")},
    };
  }

  /**
   * @method
   * @name bingx#fetchOpenInterest
   * @description retrieves the open interest of a trading pair
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Swap/Market%20Data/Open%20Interest%20Statistics
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Coin-M%20Futures/Market%20Data/Get%20Swap%20Open%20Positions
   * @param {string} symbol unified CCXT market symbol
   * @param {object} [params] exchange specific parameters
   * @returns {object} an open interest structure{@link
   * https://docs.ccxt.com/?id=open-interest-structure}
   */
  std::shared_future<ccxt::any>
  fetchOpenInterest(ccxt::any symbol,
                    ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("inverse")),
                                    true))) {
                   response =
                       awaitValue(this->cswapV1PublicGetMarketOpenInterest(
                           this->extend(request, params)));
                 } else {
                   response = awaitValue(this->swapV2PublicGetQuoteOpenInterest(
                       this->extend(request, params)));
                 }
                 //
                 // linear swap
                 //
                 //     {
                 //         "code": 0,
                 //         "msg": "",
                 //         "data": {
                 //           "openInterest": "3289641547.10",
                 //           "symbol": "BTC-USDT",
                 //           "time": 1672026617364
                 //         }
                 //     }
                 //
                 // inverse swap
                 //
                 //     {
                 //         "code": 0,
                 //         "msg": "",
                 //         "timestamp": 1720328247986,
                 //         "data": [
                 //             {
                 //                 "symbol": "BTC-USD",
                 //                 "openInterest": "749.1160",
                 //                 "timestamp": 1720310400000
                 //             }
                 //         ]
                 //     }
                 //
                 ccxt::any result = ccxt::dict{};
                 if (isTrue(isEqual(::getValue(market, std::string("inverse")),
                                    true))) {
                   ccxt::any data = this->safeList(
                       response, std::string("data"), ccxt::list{});
                   result = this->safeDict(data, 0, ccxt::dict{});
                 } else {
                   result = this->safeDict(response, std::string("data"),
                                           ccxt::dict{});
                 }
                 return this->parseOpenInterest(result, market);
               })
        .share();
  }

  ccxt::any parseOpenInterest(ccxt::any interest,
                              ccxt::any market = ccxt::any{}) override {
    //
    // linear swap
    //
    //     {
    //         "openInterest": "3289641547.10",
    //         "symbol": "BTC-USDT",
    //         "time": 1672026617364
    //     }
    //
    // inverse swap
    //
    //     {
    //         "symbol": "BTC-USD",
    //         "openInterest": "749.1160",
    //         "timestamp": 1720310400000
    //     }
    //
    ccxt::any timestamp = this->safeInteger2(interest, std::string("time"),
                                             std::string("timestamp"));
    ccxt::any id = this->safeString(interest, std::string("symbol"));
    ccxt::any symbol =
        this->safeSymbol(id, market, std::string("-"), std::string("swap"));
    ccxt::any openInterest =
        this->safeNumber(interest, std::string("openInterest"));
    ccxt::any inverse = this->safeBool(market, std::string("inverse"), false);
    ccxt::any isInverse = (isEqual(inverse, true));
    ccxt::any openInterestAmount =
        (isTrue(isInverse) ? ccxt::any(openInterest) : ccxt::any(ccxt::any{}));
    ccxt::any openInterestValue =
        (isTrue(isInverse) ? ccxt::any(ccxt::any{}) : ccxt::any(openInterest));
    return this->safeOpenInterest(
        ccxt::dict{
            {std::string("symbol"), symbol},
            {std::string("baseVolume"), ccxt::any{}},
            {std::string("quoteVolume"), ccxt::any{}},
            {std::string("openInterestAmount"), openInterestAmount},
            {std::string("openInterestValue"), openInterestValue},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("info"), interest},
        },
        market);
  }

  /**
   * @method
   * @name bingx#fetchTicker
   * @description fetches a price ticker, a statistical calculation with the
   * information calculated over the past 24 hours for a specific market
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Spot/Market%20Data/24hr%20Ticker%20Price%20Change%20Statistics
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Swap/Market%20Data/24hr%20Ticker%20Price%20Change%20Statistics
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Coin-M%20Futures/Market%20Data/Query%2024-Hour%20Price%20Change
   * @param {string} symbol unified symbol of the market to fetch the ticker for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [ticker structure]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  fetchTicker(ccxt::any symbol, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("spot")),
                                    true))) {
                   response = awaitValue(this->spotV1PublicGetTicker24hr(
                       this->extend(request, params)));
                 } else {
                   if (isTrue(isEqual(
                           ::getValue(market, std::string("inverse")), true))) {
                     response = awaitValue(this->cswapV1PublicGetMarketTicker(
                         this->extend(request, params)));
                   } else {
                     response = awaitValue(this->swapV2PublicGetQuoteTicker(
                         this->extend(request, params)));
                   }
                 }
                 //
                 // spot and swap
                 //
                 //     {
                 //         "code": 0,
                 //         "msg": "",
                 //         "timestamp": 1720647285296,
                 //         "data": [
                 //             {
                 //                 "symbol": "SOL-USD",
                 //                 "priceChange": "-2.418",
                 //                 "priceChangePercent": "-1.6900%",
                 //                 "lastPrice": "140.574",
                 //                 "lastQty": "1",
                 //                 "highPrice": "146.190",
                 //                 "lowPrice": "138.586",
                 //                 "volume": "1464648.00",
                 //                 "quoteVolume": "102928.12",
                 //                 "openPrice": "142.994",
                 //                 "closeTime": "1720647284976",
                 //                 "bidPrice": "140.573",
                 //                 "bidQty": "372",
                 //                 "askPrice": "140.577",
                 //                 "askQty": "58"
                 //             }
                 //         ]
                 //     }
                 //
                 ccxt::any data = this->safeList(response, std::string("data"));
                 if (isTrue(!isEqual(data, ccxt::any{}))) {
                   ccxt::any first = this->safeDict(data, 0, ccxt::dict{});
                   return this->parseTicker(first, market);
                 }
                 ccxt::any dataDict = this->safeDict(
                     response, std::string("data"), ccxt::dict{});
                 return this->parseTicker(dataDict, market);
               })
        .share();
  }

  /**
   * @method
   * @name bingx#fetchTickers
   * @description fetches price tickers for multiple markets, statistical
   * information calculated over the past 24 hours for each market
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Spot/Market%20Data/24hr%20Ticker%20Price%20Change%20Statistics
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Swap/Market%20Data/24hr%20Ticker%20Price%20Change%20Statistics
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Coin-M%20Futures/Market%20Data/Query%2024-Hour%20Price%20Change
   * @param {string[]|undefined} symbols unified symbols of the markets to fetch
   * the ticker for, all market tickers are returned if not assigned
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [ticker structures]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  fetchTickers(ccxt::any symbols = ccxt::any{},
               ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbols, ccxt::any{}))) {
                   symbols = this->marketSymbols(symbols);
                   ccxt::any firstSymbol = this->safeString(symbols, 0);
                   if (isTrue(!isEqual(firstSymbol, ccxt::any{}))) {
                     market = this->market(firstSymbol);
                   }
                 }
                 ccxt::any type = ccxt::any{};
                 ccxt::any typeparamsVariable = this->handleMarketTypeAndParams(
                     std::string("fetchTickers"), market, params);
                 type = ::getValue(typeparamsVariable, 0);
                 params = ::getValue(typeparamsVariable, 1);
                 ccxt::any subType = ccxt::any{};
                 ccxt::any subTypeparamsVariable = this->handleSubTypeAndParams(
                     std::string("fetchTickers"), market, params);
                 subType = ::getValue(subTypeparamsVariable, 0);
                 params = ::getValue(subTypeparamsVariable, 1);
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(type, std::string("spot")))) {
                   response =
                       awaitValue(this->spotV1PublicGetTicker24hr(params));
                 } else {
                   if (isTrue(isEqual(subType, std::string("inverse")))) {
                     response =
                         awaitValue(this->cswapV1PublicGetMarketTicker(params));
                   } else {
                     response =
                         awaitValue(this->swapV2PublicGetQuoteTicker(params));
                   }
                 }
                 //
                 // spot and swap
                 //
                 //     {
                 //         "code": 0,
                 //         "msg": "",
                 //         "timestamp": 1720647285296,
                 //         "data": [
                 //             {
                 //                 "symbol": "SOL-USD",
                 //                 "priceChange": "-2.418",
                 //                 "priceChangePercent": "-1.6900%",
                 //                 "lastPrice": "140.574",
                 //                 "lastQty": "1",
                 //                 "highPrice": "146.190",
                 //                 "lowPrice": "138.586",
                 //                 "volume": "1464648.00",
                 //                 "quoteVolume": "102928.12",
                 //                 "openPrice": "142.994",
                 //                 "closeTime": "1720647284976",
                 //                 "bidPrice": "140.573",
                 //                 "bidQty": "372",
                 //                 "askPrice": "140.577",
                 //                 "askQty": "58"
                 //             },
                 //             ...
                 //         ]
                 //     }
                 //
                 ccxt::any tickers =
                     this->safeList(response, std::string("data"));
                 return this->parseTickers(tickers, symbols);
               })
        .share();
  }

  /**
   * @method
   * @name bingx#fetchMarkPrice
   * @description fetches mark prices for the market
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Swap/Market%20Data/Mark%20Price%20and%20Funding%20Rate
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Coin-M%20Futures/Market%20Data/Price%20%26%20Current%20Funding%20Rate
   * @param {string} symbol unified symbol of the market to fetch the ticker for
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [ticker structures]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  fetchMarkPrice(ccxt::any symbol, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any subType = ccxt::any{};
                 ccxt::any subTypeparamsVariable = this->handleSubTypeAndParams(
                     std::string("fetchMarkPrice"), market, params,
                     std::string("linear"));
                 subType = ::getValue(subTypeparamsVariable, 0);
                 params = ::getValue(subTypeparamsVariable, 1);
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(subType, std::string("inverse")))) {
                   response =
                       awaitValue(this->cswapV1PublicGetMarketPremiumIndex(
                           this->extend(request, params)));
                 } else {
                   response = awaitValue(this->swapV2PublicGetQuotePremiumIndex(
                       this->extend(request, params)));
                 }
                 if (isTrue(
                         isArray(::getValue(response, std::string("data"))))) {
                   return this->parseTicker(
                       this->safeDict(::getValue(response, std::string("data")),
                                      0, ccxt::dict{}),
                       market);
                 }
                 return this->parseTicker(
                     ::getValue(response, std::string("data")), market);
               })
        .share();
  }

  /**
   * @method
   * @name bingx#fetchMarkPrices
   * @description fetches mark prices for multiple markets
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Swap/Market%20Data/Mark%20Price%20and%20Funding%20Rate
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Coin-M%20Futures/Market%20Data/Price%20%26%20Current%20Funding%20Rate
   * @param {string[]} [symbols] unified symbols of the markets to fetch the
   * ticker for, all market tickers are returned if not assigned
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a dictionary of [ticker structures]{@link
   * https://docs.ccxt.com/?id=ticker-structure}
   */
  std::shared_future<ccxt::any>
  fetchMarkPrices(ccxt::any symbols = ccxt::any{},
                  ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                          awaitValue(this->loadMarkets());
                        }
                        ccxt::any market = ccxt::any{};
                        if (isTrue(!isEqual(symbols, ccxt::any{}))) {
                          symbols = this->marketSymbols(symbols);
                          ccxt::any firstSymbol = this->safeString(symbols, 0);
                          if (isTrue(!isEqual(firstSymbol, ccxt::any{}))) {
                            market = this->market(firstSymbol);
                          }
                        }
                        ccxt::any subType = ccxt::any{};
                        ccxt::any subTypeparamsVariable =
                            this->handleSubTypeAndParams(
                                std::string("fetchMarkPrices"), market, params,
                                std::string("linear"));
                        subType = ::getValue(subTypeparamsVariable, 0);
                        params = ::getValue(subTypeparamsVariable, 1);
                        ccxt::any response = ccxt::any{};
                        if (isTrue(isEqual(subType, std::string("inverse")))) {
                          response = awaitValue(
                              this->cswapV1PublicGetMarketPremiumIndex(params));
                        } else {
                          response = awaitValue(
                              this->swapV2PublicGetQuotePremiumIndex(params));
                        }
                        //
                        // spot and swap
                        //
                        //     {
                        //         "code": 0,
                        //         "msg": "",
                        //         "timestamp": 1720647285296,
                        //         "data": [
                        //             {
                        //                 "symbol": "SOL-USD",
                        //                 "priceChange": "-2.418",
                        //                 "priceChangePercent": "-1.6900%",
                        //                 "lastPrice": "140.574",
                        //                 "lastQty": "1",
                        //                 "highPrice": "146.190",
                        //                 "lowPrice": "138.586",
                        //                 "volume": "1464648.00",
                        //                 "quoteVolume": "102928.12",
                        //                 "openPrice": "142.994",
                        //                 "closeTime": "1720647284976",
                        //                 "bidPrice": "140.573",
                        //                 "bidQty": "372",
                        //                 "askPrice": "140.577",
                        //                 "askQty": "58"
                        //             },
                        //             ...
                        //         ]
                        //     }
                        //
                        ccxt::any tickers =
                            this->safeList(response, std::string("data"));
                        return this->parseTickers(tickers, symbols);
                      })
        .share();
  }

  ccxt::any parseTicker(ccxt::any ticker,
                        ccxt::any market = ccxt::any{}) override {
    //
    // mark price
    // {
    //     "symbol": "string",
    //     "lastFundingRate": "string",
    //     "markPrice": "string",
    //     "indexPrice": "string",
    //     "nextFundingTime": "int64"
    // }
    //
    // spot
    //    {
    //        "symbol": "BTC-USDT",
    //        "openPrice": "26032.08",
    //        "highPrice": "26178.86",
    //        "lowPrice": "25968.18",
    //        "lastPrice": "26113.60",
    //        "volume": "1161.79",
    //        "quoteVolume": "30288466.44",
    //        "openTime": "1693081020762",
    //        "closeTime": "1693167420762",
    //  added 2023-11-10:
    //        "bidPrice": 16726.0,
    //        "bidQty": 0.05,
    //        "askPrice": 16726.0,
    //        "askQty": 0.05,
    //    }
    // swap
    //
    //    {
    //        "symbol": "BTC-USDT",
    //        "priceChange": "52.5",
    //        "priceChangePercent": "0.31%", // they started to add the percent
    //        sign in value "lastPrice": "16880.5", "lastQty": "2.2238", // only
    //        present in swap! "highPrice": "16897.5", "lowPrice": "16726.0",
    //        "volume": "245870.1692",
    //        "quoteVolume": "4151395117.73",
    //        "openPrice": "16832.0",
    //        "openTime": 1672026667803,
    //        "closeTime": 1672026648425,
    //  added 2023-11-10:
    //        "bidPrice": 16726.0,
    //        "bidQty": 0.05,
    //        "askPrice": 16726.0,
    //        "askQty": 0.05,
    //    }
    //
    ccxt::any marketId = this->safeString(ticker, std::string("symbol"));
    ccxt::any lastQty = this->safeString(ticker, std::string("lastQty"));
    // in spot markets, lastQty is not present
    // it's (bad, but) the only way we can check the tickers origin
    ccxt::any type = (isTrue((isEqual(lastQty, ccxt::any{})))
                          ? ccxt::any(std::string("spot"))
                          : ccxt::any(std::string("swap")));
    market = this->safeMarket(marketId, market, ccxt::any{}, type);
    ccxt::any symbol = ::getValue(market, std::string("symbol"));
    ccxt::any open = this->safeString(ticker, std::string("openPrice"));
    ccxt::any high = this->safeString(ticker, std::string("highPrice"));
    ccxt::any low = this->safeString(ticker, std::string("lowPrice"));
    ccxt::any close = this->safeString(ticker, std::string("lastPrice"));
    ccxt::any quoteVolume =
        this->safeString(ticker, std::string("quoteVolume"));
    ccxt::any baseVolume = this->safeString(ticker, std::string("volume"));
    ccxt::any percentage =
        this->safeString(ticker, std::string("priceChangePercent"));
    if (isTrue(!isEqual(percentage, ccxt::any{}))) {
      percentage = replace(percentage, std::string("%"), std::string(""));
    }
    ccxt::any change = this->safeString(ticker, std::string("priceChange"));
    ccxt::any ts = this->safeInteger(ticker, std::string("closeTime"));
    if (isTrue(isEqual(ts, 0))) {
      ts = ccxt::any{};
    }
    ccxt::any datetime = this->iso8601(ts);
    ccxt::any bid = this->safeString(ticker, std::string("bidPrice"));
    ccxt::any bidVolume = this->safeString(ticker, std::string("bidQty"));
    ccxt::any ask = this->safeString(ticker, std::string("askPrice"));
    ccxt::any askVolume = this->safeString(ticker, std::string("askQty"));
    return this->safeTicker(
        ccxt::dict{
            {std::string("symbol"), symbol},
            {std::string("timestamp"), ts},
            {std::string("datetime"), datetime},
            {std::string("high"), high},
            {std::string("low"), low},
            {std::string("bid"), bid},
            {std::string("bidVolume"), bidVolume},
            {std::string("ask"), ask},
            {std::string("askVolume"), askVolume},
            {std::string("vwap"), ccxt::any{}},
            {std::string("open"), open},
            {std::string("close"), close},
            {std::string("last"), ccxt::any{}},
            {std::string("previousClose"), ccxt::any{}},
            {std::string("change"), change},
            {std::string("percentage"), percentage},
            {std::string("average"), ccxt::any{}},
            {std::string("baseVolume"), baseVolume},
            {std::string("quoteVolume"), quoteVolume},
            {std::string("markPrice"),
             this->safeString(ticker, std::string("markPrice"))},
            {std::string("indexPrice"),
             this->safeString(ticker, std::string("indexPrice"))},
            {std::string("info"), ticker},
        },
        market);
  }

  /**
   * @method
   * @name bingx#fetchBalance
   * @description query for balance and get the amount of funds available for
   * trading or funds locked in orders
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Spot/Account%20Endpoints/Query%20Assets
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Swap/Account%20Endpoints/Query%20account%20data
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Coin-M%20Futures/Trades%20Endpoints/Query%20Account%20Assets
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Account%20and%20Wallet/Fund%20Account/Query%20Assets
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.standard] whether to fetch standard contract
   * balances
   * @param {string} [params.type] the type of balance to fetch (spot, swap,
   * funding) default is `spot`
   * @returns {object} a [balance structure]{@link
   * https://docs.ccxt.com/?id=balance-structure}
   */
  std::shared_future<ccxt::any>
  fetchBalance(ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any response = ccxt::any{};
                 ccxt::any standard = ccxt::any{};
                 ccxt::any standardparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchBalance"),
                     std::string("standard"), false);
                 standard = ::getValue(standardparamsVariable, 0);
                 params = ::getValue(standardparamsVariable, 1);
                 ccxt::any subType = ccxt::any{};
                 ccxt::any subTypeparamsVariable = this->handleSubTypeAndParams(
                     std::string("fetchBalance"), ccxt::any{}, params);
                 subType = ::getValue(subTypeparamsVariable, 0);
                 params = ::getValue(subTypeparamsVariable, 1);
                 ccxt::any marketTypemarketTypeQueryVariable =
                     this->handleMarketTypeAndParams(
                         std::string("fetchBalance"), ccxt::any{}, params);
                 ccxt::any marketType =
                     ::getValue(marketTypemarketTypeQueryVariable, 0);
                 ccxt::any marketTypeQuery =
                     ::getValue(marketTypemarketTypeQueryVariable, 1);
                 if (isTrue(standard)) {
                   response = awaitValue(
                       this->contractV1PrivateGetBalance(marketTypeQuery));
                 } else if (isTrue(isTrue((isEqual(marketType,
                                                   std::string("funding")))) ||
                                   isTrue((isEqual(marketType,
                                                   std::string("fund")))))) {
                   response = awaitValue(
                       this->fundV1PrivateGetAccountBalance(marketTypeQuery));
                 } else if (isTrue(isEqual(marketType, std::string("spot")))) {
                   response = awaitValue(
                       this->spotV1PrivateGetAccountBalance(marketTypeQuery));
                 } else {
                   if (isTrue(isEqual(subType, std::string("inverse")))) {
                     response = awaitValue(
                         this->cswapV1PrivateGetUserBalance(marketTypeQuery));
                   } else {
                     response = awaitValue(
                         this->swapV3PrivateGetUserBalance(marketTypeQuery));
                   }
                 }
                 return this->parseBalance(response);
               })
        .share();
  }

  ccxt::any parseBalance(ccxt::any response) override {
    //
    // standard
    //
    //     {
    //         "code": 0,
    //         "timestamp": 1721192833454,
    //         "data": [
    //             {
    //                 "asset": "USDT",
    //                 "balance": "4.72644300000000000000",
    //                 "crossWalletBalance": "4.72644300000000000000",
    //                 "crossUnPnl": "0",
    //                 "availableBalance": "4.72644300000000000000",
    //                 "maxWithdrawAmount": "4.72644300000000000000",
    //                 "marginAvailable": false,
    //                 "updateTime": 1721192833443
    //             },
    //         ]
    //     }
    //
    // spot
    //
    //     {
    //         "code": 0,
    //         "msg": "",
    //         "debugMsg": "",
    //         "data": {
    //             "balances": [
    //                 {
    //                     "asset": "USDT",
    //                     "free": "45.733046995800514",
    //                     "locked": "0"
    //                 },
    //             ]
    //         }
    //     }
    //
    // inverse swap
    //
    //     {
    //         "code": 0,
    //         "msg": "",
    //         "timestamp": 1721191833813,
    //         "data": [
    //             {
    //                 "asset": "SOL",
    //                 "balance": "0.35707951",
    //                 "equity": "0.35791051",
    //                 "unrealizedProfit": "0.00083099",
    //                 "availableMargin": "0.35160653",
    //                 "usedMargin": "0.00630397",
    //                 "freezedMargin": "0",
    //                 "shortUid": "12851936"
    //             }
    //         ]
    //     }
    //
    // linear swap
    //
    //     {
    //         "code": 0,
    //         "msg": "",
    //         "data": [
    //             {
    //                 "userId": "116***295",
    //                 "asset": "USDT",
    //                 "balance": "194.8212",
    //                 "equity": "196.7431",
    //                 "unrealizedProfit": "1.9219",
    //                 "realisedProfit": "-109.2504",
    //                 "availableMargin": "193.7609",
    //                 "usedMargin": "1.0602",
    //                 "freezedMargin": "0.0000",
    //                 "shortUid": "12851936"
    //             }
    //         ]
    //     }
    //
    ccxt::any result = ccxt::dict{
        {std::string("info"), response},
    };
    ccxt::any contractBalances = this->safeList(response, std::string("data"));
    ccxt::any firstContractBalances = this->safeDict(contractBalances, 0);
    ccxt::any isContract = !isEqual(firstContractBalances, ccxt::any{});
    ccxt::any spotData =
        this->safeDict(response, std::string("data"), ccxt::dict{});
    ccxt::any spotBalances = this->safeList2(
        spotData, std::string("balances"), std::string("assets"), ccxt::list{});
    if (isTrue(isContract)) {
      for (ccxt::any i = 0; isLessThan(i, getArrayLength(contractBalances));
           postFixIncrement(i)) {
        ccxt::any balance = ::getValue(contractBalances, i);
        ccxt::any currencyId = this->safeString(balance, std::string("asset"));
        if (isTrue(isEqual(currencyId, ccxt::any{}))) {
          break;
        }
        ccxt::any code = this->safeCurrencyCode(currencyId);
        ccxt::any account = this->account();
        ::setValue(account, std::string("free"),
                   this->safeString2(balance, std::string("availableMargin"),
                                     std::string("availableBalance")));
        ::setValue(account, std::string("used"),
                   this->safeString(balance, std::string("usedMargin")));
        ::setValue(account, std::string("total"),
                   this->safeString(balance, std::string("maxWithdrawAmount")));
        if (isTrue(!isEqual(code, ccxt::any{}))) {
          ::setValue(result, code, account);
        }
      }
    } else {
      for (ccxt::any i = 0; isLessThan(i, getArrayLength(spotBalances));
           postFixIncrement(i)) {
        ccxt::any balance = ::getValue(spotBalances, i);
        ccxt::any currencyId = this->safeString(balance, std::string("asset"));
        ccxt::any code = this->safeCurrencyCode(currencyId);
        ccxt::any account = this->account();
        ::setValue(account, std::string("free"),
                   this->safeString(balance, std::string("free")));
        ::setValue(account, std::string("used"),
                   this->safeString(balance, std::string("locked")));
        if (isTrue(!isEqual(code, ccxt::any{}))) {
          ::setValue(result, code, account);
        }
      }
    }
    return this->safeBalance(result);
  }

  /**
   * @method
   * @name bingx#fetchPositionHistory
   * @description fetches historical positions
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Swap/Trades%20Endpoints/Query%20Position%20History
   * @param {string} symbol unified contract symbol
   * @param {int} [since] the earliest time in ms to fetch positions for
   * @param {int} [limit] the maximum amount of records to fetch
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch positions for
   * @returns {object[]} a list of [position structures]{@link
   * https://docs.ccxt.com/?id=position-structure}
   */
  std::shared_future<ccxt::any>
  fetchPositionHistory(ccxt::any symbol, ccxt::any since = ccxt::any{},
                       ccxt::any limit = ccxt::any{},
                       ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("pageSize"), limit);
                 }
                 if (isTrue(!isEqual(since, ccxt::any{}))) {
                   ::setValue(request, std::string("startTs"), since);
                 }
                 ccxt::any requestparamsVariable = this->handleUntilOption(
                     std::string("endTs"), request, params);
                 request = ::getValue(requestparamsVariable, 0);
                 params = ::getValue(requestparamsVariable, 1);
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("linear")),
                                    true))) {
                   response =
                       awaitValue(this->swapV1PrivateGetTradePositionHistory(
                           this->extend(request, params)));
                 } else {
                   throw NotSupported(toString(add(
                       this->id,
                       std::string(" fetchPositionHistory() is not supported "
                                   "for inverse swap positions"))));
                 }
                 //
                 //     {
                 //         "code": 0,
                 //         "msg": "",
                 //         "data": {
                 //             "positionHistory": [
                 //                 {
                 //                     "positionId": "1861675561156571136",
                 //                     "symbol": "LTC-USDT",
                 //                     "isolated": false,
                 //                     "positionSide": "LONG",
                 //                     "openTime": 1732693017000,
                 //                     "updateTime": 1733310292000,
                 //                     "avgPrice": "95.18",
                 //                     "avgClosePrice": "129.48",
                 //                     "realisedProfit": "102.89",
                 //                     "netProfit": "99.63",
                 //                     "positionAmt": "30.0",
                 //                     "closePositionAmt": "30.0",
                 //                     "leverage": 6,
                 //                     "closeAllPositions": true,
                 //                     "positionCommission":
                 //                     "-0.33699650000000003", "totalFunding":
                 //                     "-2.921461693902908"
                 //                 },
                 //             ]
                 //         }
                 //     }
                 //
                 ccxt::any data = this->safeDict(response, std::string("data"),
                                                 ccxt::dict{});
                 ccxt::any records = this->safeList(
                     data, std::string("positionHistory"), ccxt::list{});
                 ccxt::any positions = this->parsePositions(records);
                 return this->filterBySymbolSinceLimit(positions, symbol, since,
                                                       limit);
               })
        .share();
  }

  /**
   * @method
   * @name bingx#fetchPositions
   * @description fetch all open positions
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Swap/Account%20Endpoints/Query%20position%20data
   * @see
   * https://bingx-api.github.io/docs/#/en-us/standard/contract-interface.html#position
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Coin-M%20Futures/Trades%20Endpoints/Query%20warehouse
   * @param {string[]|undefined} symbols list of unified market symbols
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {boolean} [params.standard] whether to fetch standard contract
   * positions
   * @returns {object[]} a list of [position structures]{@link
   * https://docs.ccxt.com/?id=position-structure}
   */
  std::shared_future<ccxt::any>
  fetchPositions(ccxt::any symbols = ccxt::any{},
                 ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 symbols = this->marketSymbols(symbols);
                 ccxt::any standard = ccxt::any{};
                 ccxt::any standardparamsVariable = this->handleOptionAndParams(
                     params, std::string("fetchPositions"),
                     std::string("standard"), false);
                 standard = ::getValue(standardparamsVariable, 0);
                 params = ::getValue(standardparamsVariable, 1);
                 ccxt::any response = ccxt::any{};
                 if (isTrue(standard)) {
                   response = awaitValue(
                       this->contractV1PrivateGetAllPosition(params));
                 } else {
                   ccxt::any market = ccxt::any{};
                   if (isTrue(!isEqual(symbols, ccxt::any{}))) {
                     symbols = this->marketSymbols(symbols);
                     ccxt::any firstSymbol = this->safeString(symbols, 0);
                     if (isTrue(!isEqual(firstSymbol, ccxt::any{}))) {
                       market = this->market(firstSymbol);
                     }
                   }
                   ccxt::any subType = ccxt::any{};
                   ccxt::any subTypeparamsVariable =
                       this->handleSubTypeAndParams(
                           std::string("fetchPositions"), market, params);
                   subType = ::getValue(subTypeparamsVariable, 0);
                   params = ::getValue(subTypeparamsVariable, 1);
                   if (isTrue(isEqual(subType, std::string("inverse")))) {
                     response = awaitValue(
                         this->cswapV1PrivateGetUserPositions(params));
                   } else {
                     response = awaitValue(
                         this->swapV2PrivateGetUserPositions(params));
                   }
                 }
                 ccxt::any positions = this->safeList(
                     response, std::string("data"), ccxt::list{});
                 return this->parsePositions(positions, symbols);
               })
        .share();
  }

  /**
   * @method
   * @name bingx#fetchPosition
   * @description fetch data on a single open contract trade position
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Swap/Account%20Endpoints/Query%20position%20data
   * @see
   * https://bingx-api.github.io/docs-v3/#/en/Coin-M%20Futures/Trades%20Endpoints/Query%20warehouse
   * @param {string} symbol unified market symbol of the market the position is
   * held in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [position structure]{@link
   * https://docs.ccxt.com/?id=position-structure}
   */
  std::shared_future<ccxt::any>
  fetchPosition(ccxt::any symbol, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 if (isTrue(!isEqual(::getValue(market, std::string("swap")),
                                     true))) {
                   throw BadRequest(toString(add(
                       this->id,
                       std::string(
                           " fetchPosition() supports swap markets only"))));
                 }
                 ccxt::any request = ccxt::dict{
                     {std::string("symbol"),
                      ::getValue(market, std::string("id"))},
                 };
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(::getValue(market, std::string("inverse")),
                                    true))) {
                   response = awaitValue(this->cswapV1PrivateGetUserPositions(
                       this->extend(request, params)));
                 } else {
                   response = awaitValue(this->swapV2PrivateGetUserPositions(
                       this->extend(request, params)));
                 }
                 ccxt::any data = this->safeList(response, std::string("data"),
                                                 ccxt::list{});
                 ccxt::any first = this->safeDict(data, 0, ccxt::dict{});
                 return this->parsePosition(first, market);
               })
        .share();
  }

  ccxt::any parsePosition(ccxt::any position,
                          ccxt::any market = ccxt::any{}) override {
    //
    // inverse swap
    //
    //     {
    //         "symbol": "SOL-USD",
    //         "positionId": "1813080351385337856",
    //         "positionSide": "LONG",
    //         "isolated": false,
    //         "positionAmt": "1",
    //         "availableAmt": "1",
    //         "unrealizedProfit": "-0.00009074",
    //         "initialMargin": "0.00630398",
    //         "liquidationPrice": 23.968303426677032,
    //         "avgPrice": "158.63",
    //         "leverage": 10,
    //         "markPrice": "158.402",
    //         "riskRate": "0.00123783",
    //         "maxMarginReduction": "0",
    //         "updateTime": 1721107015848
    //     }
    //
    // linear swap
    //
    //     {
    //         "positionId": "1792480725958881280",
    //         "symbol": "LTC-USDT",
    //         "currency": "USDT",
    //         "positionAmt": "0.1",
    //         "availableAmt": "0.1",
    //         "positionSide": "LONG",
    //         "isolated": false,
    //         "avgPrice": "83.53",
    //         "initialMargin": "1.3922",
    //         "margin": "0.3528",
    //         "leverage": 6,
    //         "unrealizedProfit": "-1.0393",
    //         "realisedProfit": "-0.2119",
    //         "liquidationPrice": 0,
    //         "pnlRatio": "-0.7465",
    //         "maxMarginReduction": "0.0000",
    //         "riskRate": "0.0008",
    //         "markPrice": "73.14",
    //         "positionValue": "7.3136",
    //         "onlyOnePosition": true,
    //         "updateTime": 1721088016688
    //     }
    //
    // standard position
    //
    //     {
    //         "currentPrice": "82.91",
    //         "symbol": "LTC/USDT",
    //         "initialMargin": "5.00000000000000000000",
    //         "unrealizedProfit": "-0.26464500",
    //         "leverage": "20.000000000",
    //         "isolated": true,
    //         "entryPrice": "83.13",
    //         "positionSide": "LONG",
    //         "positionAmt": "1.20365912",
    //     }
    //
    // linear swap fetchPositionHistory
    //
    //     {
    //         "positionId": "1861675561156571136",
    //         "symbol": "LTC-USDT",
    //         "isolated": false,
    //         "positionSide": "LONG",
    //         "openTime": 1732693017000,
    //         "updateTime": 1733310292000,
    //         "avgPrice": "95.18",
    //         "avgClosePrice": "129.48",
    //         "realisedProfit": "102.89",
    //         "netProfit": "99.63",
    //         "positionAmt": "30.0",
    //         "closePositionAmt": "30.0",
    //         "leverage": 6,
    //         "closeAllPositions": true,
    //         "positionCommission": "-0.33699650000000003",
    //         "totalFunding": "-2.921461693902908"
    //     }
    //
    ccxt::any marketId =
        this->safeString(position, std::string("symbol"), std::string(""));
    marketId = replace(marketId, std::string("/"),
                       std::string("-")); // standard return different format
    ccxt::any isolated = this->safeBool(position, std::string("isolated"));
    ccxt::any marginMode = ccxt::any{};
    if (isTrue(!isEqual(isolated, ccxt::any{}))) {
      marginMode = (isTrue(isolated) ? ccxt::any(std::string("isolated"))
                                     : ccxt::any(std::string("cross")));
    }
    ccxt::any timestamp = this->safeInteger(position, std::string("openTime"));
    return this->safePosition(ccxt::dict{
        {std::string("info"), position},
        {std::string("id"),
         this->safeString(position, std::string("positionId"))},
        {std::string("symbol"),
         this->safeSymbol(marketId, market, std::string("-"),
                          std::string("swap"))},
        {std::string("notional"),
         this->safeNumber(position, std::string("positionValue"))},
        {std::string("marginMode"), marginMode},
        {std::string("liquidationPrice"),
         this->safeNumberOmitZero(position, std::string("liquidationPrice"))},
        {std::string("entryPrice"),
         this->safeNumber2(position, std::string("avgPrice"),
                           std::string("entryPrice"))},
        {std::string("unrealizedPnl"),
         this->safeNumber(position, std::string("unrealizedProfit"))},
        {std::string("realizedPnl"),
         this->safeNumber(position, std::string("realisedProfit"))},
        {std::string("percentage"), ccxt::any{}},
        {std::string("contracts"),
         this->safeNumber(position, std::string("positionAmt"))},
        {std::string("contractSize"), ccxt::any{}},
        {std::string("markPrice"),
         this->safeNumber(position, std::string("markPrice"))},
        {std::string("lastPrice"), ccxt::any{}},
        {std::string("side"),
         this->safeStringLower(position, std::string("positionSide"))},
        {std::string("hedged"), ccxt::any{}},
        {std::string("timestamp"), timestamp},
        {std::string("datetime"), this->iso8601(timestamp)},
        {std::string("lastUpdateTimestamp"),
         this->safeInteger(position, std::string("updateTime"))},
        {std::string("maintenanceMargin"), ccxt::any{}},
        {std::string("maintenanceMarginPercentage"), ccxt::any{}},
        {std::string("collateral"), ccxt::any{}},
        {std::string("initialMargin"),
         this->safeNumber(position, std::string("initialMargin"))},
        {std::string("initialMarginPercentage"), ccxt::any{}},
        {std::string("leverage"),
         this->safeNumber(position, std::string("leverage"))},
        {std::string("marginRatio"), ccxt::any{}},
        {std::string("stopLossPrice"), ccxt::any{}},
        {std::string("takeProfitPrice"), ccxt::any{}},
    });
  }

  /**
   * @method
   * @name bingx#createMarketOrderWithCost
   * @description create a market order by providing the symbol, side and cost
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} side 'buy' or 'sell'
   * @param {float} cost how much you want to trade in units of the quote
   * currency
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  createMarketOrderWithCost(ccxt::any symbol, ccxt::any side, ccxt::any cost,
                            ccxt::any params = ccxt::dict{}) override {
    return std::async(std::launch::deferred,
                      [=]() mutable -> ccxt::any {
                        ::setValue(params, std::string("quoteOrderQty"), cost);
                        return awaitValue(
                            this->createOrder(symbol, std::string("market"),
                                              side, cost, ccxt::any{}, params));
                      })
        .share();
  }

